	lhu  t0, 0(t0)                  # load lower 16 bits from *mepc (always 2-byte aligned)
	andi t0, t0, 3                  # t0 = bits[1:0]
	addi t0, t0, 1                  # t0 = bits[1:0]+1; equals 4 only when was 0b11
	srli t0, t0, 2                  # t0 = 1 iff uncompressed (0b11), else 0
